ERT_R = ("Hypersensitivity and infusion reactions are possible","Możliwe reakcje nadwrażliwości i na wlew","Son posibles las reacciones de hipersensibilidad y a la infusión")
def ert(year, en, pl, es):
    return ([("Approved by the FDA in %s for %s" % (year, en), "Zatwierdzona przez FDA w %s: %s" % (year, pl), "Aprobada por la FDA en %s para %s" % (year, es)),
             ("Replaces the missing enzyme, treating the cause","Zastępuje brakujący enzym, leczy przyczynę","Sustituye la enzima ausente y trata la causa")],
            [ERT_C, ERT_R])
